function openCountsByProject(projectIds, openTasks) {
  const counts = new Map();
  for (const id of projectIds) counts.set(id, 0);
  for (const task of openTasks) counts.set(task.projectId, (counts.get(task.projectId) ?? 0) + 1);
  return counts;
}

const openTasks = [{ projectId: 1 }, { projectId: 3 }, { projectId: 1 }];
console.log(openCountsByProject([1, 2, 3], openTasks));

