function pageAfter(rows, cursor, limit) {
  const isAfter = (row) =>
    cursor === null ||
    row.createdAt < cursor.createdAt ||
    (row.createdAt === cursor.createdAt && row.id < cursor.id);
  return rows.filter(isAfter).slice(0, limit);
}

