import { ConflictError, NotFoundError } from "@zudojs/errors";

const store = new Map([[3, { id: 3, title: "Compress the images", version: 1 }]]);

function saveTitle(id: number, expectedVersion: number, title: string) {
  const task = store.get(id);
  if (!task) throw new NotFoundError(`Task ${id} not found`);
  if (task.version !== expectedVersion) throw new ConflictError(`Task ${id} was changed by someone else`);
  const saved = { ...task, title, version: task.version + 1 };
  store.set(id, saved);
  return saved;
}

for (const [id, version, title] of [[3, 1, "Compress images"], [3, 1, "Shrink images"], [9, 1, "Nothing"]] as const) {
  try {
    console.log(saveTitle(id, version, title));
  } catch (error) {
    if (error instanceof ConflictError || error instanceof NotFoundError) console.log(error.statusCode, error.message);
  }
}

