const state = { openTasks: 2, tasks: new Map([[5, { id: 5, status: "open" }], [6, { id: 6, status: "open" }]]) };

function completeTask(state, id) {
  const task = state.tasks.get(id);
  if (task.status === "done") return task;
  task.status = "done";
  state.openTasks -= 1;
  return task;
}

completeTask(state, 5);
completeTask(state, 5);
completeTask(state, 5);
console.log(state.openTasks, state.tasks.get(5).status);

